-- Product storytelling is part of the storefront content, not generated at render time.
alter table public.commerce_products add column if not exists story text not null default '';

update public.commerce_products
set story = case id
  when '1' then 'I wanted the Essential Ring to be the piece you stop noticing because it already belongs on your hand. The profile stays clean, but the finish keeps enough life in the metal to avoid feeling anonymous.'
  when '2' then 'This set started with the idea that pieces should work together without looking like they were bought together. The layers are close enough to feel intentional and loose enough to make them your own.'
  when '3' then 'I kept coming back to the balance between a strong shape and a light feel. These earrings have presence from across the room, but they still move easily when you wear them.'
  when '4' then 'The Hand Combination is built for people who like to wear more than one piece but still want the whole hand to feel considered. I left small differences between the elements so it does not look factory-perfect.'
  when '5' then 'A good everyday earring should not need an occasion. This pair is deliberately uncomplicated: a little shine, a comfortable weight and a shape that works when the rest of the outfit changes.'
  when '6' then 'The Everyday Bracelet is about the quiet details you notice after wearing it for a while. The surface catches differently as the wrist moves, which is exactly what I wanted.'
  else story
end
where id in ('1','2','3','4','5','6');

on conflict (id) do update set name=excluded.name,branch=excluded.branch,category=excluded.category,description=excluded.description,image_url=excluded.image_url,price=excluded.price,discount_percent=excluded.discount_percent,active=excluded.active,story=excluded.story,updated_at=now();
